1	//! Ranks code blocks by BM25 relevance, boosted by symbol kind and by how many matched lines each block covers.
2	
3	mod bm25;
4	mod boost;
5	mod tokenize_doc;
6	
7	use std::cmp::Ordering;
8	use std::collections::HashMap;
9	use std::hash::BuildHasher;
10	
11	pub use bm25::{round6, score};
12	pub use boost::{coverage_boost, node_type_boost};
13	pub use tokenize_doc::tokenize_block;
14	
15	use crate::types::{CodeBlock, RankedBlock, SymbolKind};
16	
17	/// Scores each block against `query_terms` and returns them best first, with 1-based ranks.
18	///
19	/// Each block comes with its document tokens, usually from [`tokenize_block`]. The corpus for BM25 is `blocks`
20	/// itself: its size and average token count feed [`score`], and `df` gives each term's document frequency. A block's
21	/// `final_score` is `round6(bm25 * node_type_boost + coverage_boost)`.
22	///
23	/// The order is `final_score` descending (with `-0.0` equal to `0.0`), then ascending `file` by path components,
24	/// `line_start`, `line_end`, `node_kind` in `SymbolKind` declaration order, and `code` by bytes. Reordering the input
25	/// never reorders the output, except that blocks equal on all six keys keep their relative input order.
26	///
27	/// # Examples
28	///
29	/// ```
30	/// use std::collections::HashMap;
31	///
32	/// use camino::Utf8PathBuf;
33	/// use monokl::rank::{rank_blocks, tokenize_block};
34	/// use monokl::types::{CodeBlock, SymbolKind};
35	///
36	/// let block = |file: &str, code: &str| CodeBlock {
37	///     file: Utf8PathBuf::from(file),
38	///     line_start: 1,
39	///     line_end: 1,
40	///     node_kind: SymbolKind::Function,
41	///     code: code.to_string(),
42	///     symbol_signature: None,
43	///     matched_lines: Vec::new(),
44	///     matched_keywords: Vec::new(),
45	/// };
46	/// let blocks: Vec<_> = [block("b.ts", "parseConfig()"), block("a.ts", "readFile()")]
47	///     .into_iter()
48	///     .map(|b| {
49	///         let tokens = tokenize_block(&b);
50	///         (b, tokens)
51	///     })
52	///     .collect();
53	/// let df = HashMap::from([("config".to_string(), 1)]);
54	///
55	/// let ranked = rank_blocks(blocks, &["config"], &df);
56	/// assert_eq!(ranked[0].block.file, "b.ts");
57	/// assert_eq!(ranked[0].rank, 1);
58	/// assert_eq!(ranked[1].final_score, 0.0);
59	/// ```
60	pub fn rank_blocks<S: BuildHasher>(
61	    blocks: Vec<(CodeBlock, Vec<String>)>,
62	    query_terms: &[&str],
63	    df: &HashMap<String, usize, S>,
64	) -> Vec<RankedBlock> {
65	    if blocks.is_empty() {
66	        return Vec::new();
67	    }
68	    let corpus_size = blocks.len();
69	    let total_tokens: usize = blocks.iter().map(|(_, tokens)| tokens.len()).sum();
70	    let avg_doc_len = bm25::as_f64(total_tokens) / bm25::as_f64(corpus_size);
71	    let mut ranked: Vec<RankedBlock> = blocks
72	        .into_iter()
73	        .map(|(block, doc_tokens)| {
74	            let bm25_score = score(&doc_tokens, query_terms, avg_doc_len, corpus_size, df);
75	            let coverage_boost = coverage_boost(&block);
76	            let node_type_boost = node_type_boost(block.node_kind);
77	            RankedBlock {
78	                block,
79	                bm25_score,
80	                coverage_boost,
81	                node_type_boost,
82	                final_score: round6(bm25_score * node_type_boost + coverage_boost),
83	                rank: 0,
84	                parent_context: None,
85	            }
86	        })
87	        .collect();
88	    ranked.sort_by(best_first);
89	    for (rank, block) in (1..).zip(&mut ranked) {
90	        block.rank = rank;
91	    }
92	    ranked
93	}
94	
95	/// Orders ranked blocks best first by a total order over everything that tells two blocks apart: `final_score`
96	/// descending, then `file` (component-wise), `line_start`, `line_end`, `node_kind` and `code` ascending.
97	///
98	/// `-0.0` and `0.0` compare equal so the sign of a zero score cannot reorder blocks; every other score, NaN included,
99	/// follows [`f64::total_cmp`].
100	fn best_first(a: &RankedBlock, b: &RankedBlock) -> Ordering {
101	    score_order(b.final_score)
102	        .total_cmp(&score_order(a.final_score))
103	        .then_with(|| a.block.file.cmp(&b.block.file))
104	        .then_with(|| a.block.line_start.cmp(&b.block.line_start))
105	        .then_with(|| a.block.line_end.cmp(&b.block.line_end))
106	        .then_with(|| kind_order(a.block.node_kind).cmp(&kind_order(b.block.node_kind)))
107	        .then_with(|| a.block.code.cmp(&b.block.code))
108	}
109	
110	/// Maps `-0.0` to `0.0`, which [`f64::total_cmp`] would otherwise order below it.
111	fn score_order(score: f64) -> f64 {
112	    if score == 0.0 { 0.0 } else { score }
113	}
114	
115	/// Returns the position of `kind` in `SymbolKind`'s declaration order.
116	fn kind_order(kind: SymbolKind) -> u8 {
117	    match kind {
118	        SymbolKind::Function => 0,
119	        SymbolKind::Method => 1,
120	        SymbolKind::Constructor => 2,
121	        SymbolKind::Class => 3,
122	        SymbolKind::Struct => 4,
123	        SymbolKind::Enum => 5,
124	        SymbolKind::Interface => 6,
125	        SymbolKind::TypeAlias => 7,
126	        SymbolKind::Property => 8,
127	        SymbolKind::Field => 9,
128	        SymbolKind::Variable => 10,
129	        SymbolKind::Module => 11,
130	        SymbolKind::Impl => 12,
131	        SymbolKind::Macro => 13,
132	        SymbolKind::Other => 14,
133	    }
134	}
