407	    /// Calls `visit` once per ordering of `items[k..]`.
408	    fn for_each_permutation<T>(items: &mut [T], k: usize, visit: &mut impl FnMut(&[T])) {
409	        if k == items.len() {
410	            visit(items);
411	            return;
412	        }
413	        for i in k..items.len() {
414	            items.swap(k, i);
415	            for_each_permutation(items, k + 1, visit);
416	            items.swap(k, i);
417	        }
418	    }
