4	/// Returns the fraction of the block's matched lines that fall inside `line_start..=line_end`, rounded with
5	/// [`round6`].
6	///
7	/// Returns 0.0 when `matched_lines` is empty. A block whose `line_end` is before its `line_start` contains no lines.
8	///
9	/// # Examples
10	///
11	/// ```
12	/// use camino::Utf8PathBuf;
13	/// use monokl::rank::coverage_boost;
14	/// use monokl::types::{CodeBlock, SymbolKind};
15	///
16	/// let block = CodeBlock {
17	///     file: Utf8PathBuf::from("src/a.ts"),
18	///     line_start: 10,
19	///     line_end: 20,
20	///     node_kind: SymbolKind::Function,
21	///     code: String::new(),
22	///     symbol_signature: None,
23	///     matched_lines: vec![12, 30, 40],
24	///     matched_keywords: Vec::new(),
25	/// };
26	/// assert_eq!(coverage_boost(&block), 0.333333);
27	/// ```
28	pub fn coverage_boost(block: &CodeBlock) -> f64 {
29	    if block.matched_lines.is_empty() {
30	        return 0.0;
31	    }
32	    let lines = block.line_start..=block.line_end;
33	    let inside = block.matched_lines.iter().filter(|line| lines.contains(*line)).count();
34	    round6(as_f64(inside) / as_f64(block.matched_lines.len()))
35	}
36	
37	/// Returns the score multiplier for a block's symbol kind.
38	///
39	/// Callable units rank highest, then type definitions, then bindings; `Other` ranks lowest.
40	///
41	/// # Examples
42	///
43	/// ```
44	/// use monokl::rank::node_type_boost;
45	/// use monokl::types::SymbolKind;
46	///
47	/// assert_eq!(node_type_boost(SymbolKind::Function), 1.5);
48	/// assert_eq!(node_type_boost(SymbolKind::Other), 0.7);
49	/// ```
50	pub fn node_type_boost(kind: SymbolKind) -> f64 {
51	    match kind {
52	        SymbolKind::Function => 1.5,
53	        SymbolKind::Class | SymbolKind::Method | SymbolKind::Constructor => 1.4,
54	        SymbolKind::Interface | SymbolKind::Struct => 1.3,
55	        SymbolKind::TypeAlias | SymbolKind::Enum => 1.2,
56	        SymbolKind::Variable | SymbolKind::Impl => 1.1,
57	        SymbolKind::Property | SymbolKind::Field | SymbolKind::Macro => 1.0,
58	        SymbolKind::Module => 0.9,
59	        SymbolKind::Other => 0.7,
60	    }
61	}
