4	const K1: f64 = 1.5;
5	const B: f64 = 0.5;
6	const DP: f64 = 1_000_000.0;
7	
8	/// Rounds `x` to 6 decimal places, halves away from zero.
9	///
10	/// Every score is rounded so output is stable across platforms and readable in agent-facing text.
11	///
12	/// # Examples
13	///
14	/// ```
15	/// use monokl::rank::round6;
16	///
17	/// assert_eq!(round6(0.1234565), 0.123457);
18	/// assert_eq!(round6(1.0000004), 1.0);
19	/// ```
20	pub fn round6(x: f64) -> f64 {
21	    (x * DP).round() / DP
22	}
23	
24	/// Returns the Okapi BM25 score of one document for `query_terms`, rounded with [`round6`].
25	///
26	/// Uses `K1 = 1.5` and `B = 0.5`. `corpus_size` is the number of documents and `df` maps a term to the number of
27	/// documents containing it; a term missing from `df` has a document frequency of 0. A query term absent from the
28	/// document contributes nothing. Term frequency is exact, case-sensitive token equality, and a term repeated in
29	/// `query_terms` counts once per occurrence. Returns 0.0 when either `doc_tokens` or `query_terms` is empty, or when
30	/// `avg_doc_len` is not a finite number above zero.
31	///
32	/// # Examples
33	///
34	/// ```
35	/// use std::collections::HashMap;
36	///
37	/// use monokl::rank::score;
38	///
39	/// let doc: Vec<String> = ["foo", "foo", "bar", "baz"].map(String::from).into();
40	/// let df = HashMap::from([("foo".to_string(), 1)]);
41	/// assert_eq!(score(&doc, &["foo"], 4.0, 2, &df), 0.99021);
42	/// ```
43	pub fn score<S: BuildHasher>(
44	    doc_tokens: &[String],
45	    query_terms: &[&str],
46	    avg_doc_len: f64,
47	    corpus_size: usize,
48	    df: &HashMap<String, usize, S>,
49	) -> f64 {
50	    // A non-positive or non-finite average length has no meaning as a corpus statistic and would turn the length
51	    // normalization into a sign flip or NaN.
52	    if query_terms.is_empty() || doc_tokens.is_empty() || !(avg_doc_len.is_finite() && avg_doc_len > 0.0) {
53	        return 0.0;
54	    }
55	    let doc_len = as_f64(doc_tokens.len());
56	    let n = as_f64(corpus_size);
57	    let mut total = 0.0;
58	    for term in query_terms {
59	        let tf = doc_tokens.iter().filter(|token| token == term).count();
60	        if tf == 0 {
61	            continue;
62	        }
63	        let tf = as_f64(tf);
64	        let df_t = as_f64(df.get(*term).copied().unwrap_or(0));
65	        let idf = ((n - df_t + 0.5) / (df_t + 0.5) + 1.0).ln();
66	        let norm_factor = K1 * (1.0 - B + B * (doc_len / avg_doc_len));
67	        total += idf * ((tf * (K1 + 1.0)) / (tf + norm_factor));
68	    }
69	    round6(total)
70	}
