37	/// Returns the score multiplier for a block's symbol kind.
38	///
39	/// Callable units rank highest, then type definitions, then bindings; `Other` ranks lowest.
40	///
41	/// # Examples
42	///
43	/// ```
44	/// use monokl::rank::node_type_boost;
45	/// use monokl::types::SymbolKind;
46	///
47	/// assert_eq!(node_type_boost(SymbolKind::Function), 1.5);
48	/// assert_eq!(node_type_boost(SymbolKind::Other), 0.7);
49	/// ```
50	pub fn node_type_boost(kind: SymbolKind) -> f64 {
51	    match kind {
52	        SymbolKind::Function => 1.5,
53	        SymbolKind::Class | SymbolKind::Method | SymbolKind::Constructor => 1.4,
54	        SymbolKind::Interface | SymbolKind::Struct => 1.3,
55	        SymbolKind::TypeAlias | SymbolKind::Enum => 1.2,
56	        SymbolKind::Variable | SymbolKind::Impl => 1.1,
57	        SymbolKind::Property | SymbolKind::Field | SymbolKind::Macro => 1.0,
58	        SymbolKind::Module => 0.9,
59	        SymbolKind::Other => 0.7,
60	    }
61	}
