4	/// Returns the BM25 document tokens of a block: its code's tokens followed by its signature's, if it has one.
5	///
6	/// # Examples
7	///
8	/// ```
9	/// use camino::Utf8PathBuf;
10	/// use monokl::rank::tokenize_block;
11	/// use monokl::types::{CodeBlock, SymbolKind};
12	///
13	/// let block = CodeBlock {
14	///     file: Utf8PathBuf::from("src/a.ts"),
15	///     line_start: 1,
16	///     line_end: 1,
17	///     node_kind: SymbolKind::Function,
18	///     code: "return userName;".to_string(),
19	///     symbol_signature: Some("fn userName()".to_string()),
20	///     matched_lines: Vec::new(),
21	///     matched_keywords: Vec::new(),
22	/// };
23	/// assert_eq!(tokenize_block(&block), ["user", "name", "user", "name"]);
24	/// ```
25	pub fn tokenize_block(block: &CodeBlock) -> Vec<String> {
26	    let mut tokens = tokenize_source(&block.code);
27	    if let Some(signature) = &block.symbol_signature {
28	        tokens.extend(tokenize_source(signature));
29	    }
30	    tokens
31	}
