1	//! Identifier tokenizing for BM25: splits camel, Pascal, snake and kebab case into lowercase sub-words.
2	
3	/// Tokens too common in prose or code to say anything about relevance.
4	///
5	/// `use` appears twice; the duplicate is harmless and kept so the list reads as the two groups it came from.
6	#[rustfmt::skip]
7	const STOP_WORDS: &[&str] = &[
8	    "the", "and", "for", "are", "but", "not", "you", "all", "can", "had", "her", "was", "one", "our", "out", "day",
9	    "get", "has", "him", "his", "how", "its", "may", "new", "now", "old", "see", "two", "use", "way", "who", "did",
10	    "let", "put", "too", "any",
11	    // Common code keywords.
12	    "fn", "var", "const", "mut", "pub", "use", "mod", "impl", "type", "enum", "struct", "trait", "return", "import",
13	    "export", "from", "default", "class", "extends", "interface",
14	    // Near-universal Rust tokens.
15	    "crate", "self", "super", "dyn", "async", "await", "unsafe",
16	];
17	
18	/// Splits one identifier into lowercase sub-words, dropping stop words and tokens shorter than 2 characters.
19	///
20	/// A new word starts at a lower-to-upper transition, at the last capital of an acronym followed by lowercase
21	/// (`XMLParser` gives `xml`, `parser`), and at a digit-to-letter transition. A letter-to-digit transition does not
22	/// split, so `v8` stays whole. Every character other than an ASCII letter or digit is a separator.
23	///
24	/// # Examples
25	///
26	/// ```
27	/// use monokl::tokens::tokenize;
28	///
29	/// assert_eq!(tokenize("XMLParser"), ["xml", "parser"]);
30	/// assert_eq!(tokenize("getUserName"), ["user", "name"]);
31	/// ```
32	pub fn tokenize(input: &str) -> Vec<String> {
33	    let chars: Vec<char> = input.chars().collect();
34	    let mut words = Vec::new();
35	    let mut word = String::new();
36	    for (idx, &ch) in chars.iter().enumerate() {
37	        if !ch.is_ascii_alphanumeric() {
38	            push_word(&mut words, &mut word);
39	            continue;
40	        }
41	        let prev = idx.checked_sub(1).and_then(|prev| chars.get(prev)).copied();
42	        let next = chars.get(idx + 1).copied();
43	        if prev.is_some_and(|prev| starts_word(prev, ch, next)) {
44	            push_word(&mut words, &mut word);
45	        }
46	        word.push(ch.to_ascii_lowercase());
47	    }
48	    push_word(&mut words, &mut word);
49	    words.retain(|word| word.len() >= 2 && !STOP_WORDS.contains(&word.as_str()));
50	    words
51	}
52	
53	/// Returns whether `ch`, preceded by `prev` and followed by `next`, begins a new sub-word.
54	fn starts_word(prev: char, ch: char, next: Option<char>) -> bool {
55	    (prev.is_ascii_lowercase() && ch.is_ascii_uppercase())
56	        || (prev.is_ascii_uppercase() && ch.is_ascii_uppercase() && next.is_some_and(|next| next.is_ascii_lowercase()))
57	        || (prev.is_ascii_digit() && ch.is_ascii_alphabetic())
58	}
59	
60	fn push_word(words: &mut Vec<String>, word: &mut String) {
61	    if !word.is_empty() {
62	        words.push(std::mem::take(word));
63	    }
64	}
65	
66	/// Splits source text on every character other than `[A-Za-z0-9_]` and tokenizes each fragment with [`tokenize`].
67	///
68	/// Duplicates are kept in source order, since BM25 needs term frequency.
69	///
70	/// # Examples
71	///
72	/// ```
73	/// use monokl::tokens::tokenize_source;
74	///
75	/// assert_eq!(tokenize_source("fooBar(fooBar)"), ["foo", "bar", "foo", "bar"]);
76	/// ```
77	pub fn tokenize_source(source: &str) -> Vec<String> {
78	    source
79	        .split(|ch: char| !(ch.is_ascii_alphanumeric() || ch == '_'))
80	        .filter(|fragment| !fragment.is_empty())
81	        .flat_map(tokenize)
82	        .collect()
83	}
