90	///
91	/// let dir = tempfile::tempdir()?;
92	/// std::fs::write(dir.path().join("a.ts"), "const alpha = 1;\n")?;
93	/// let root = Utf8Path::from_path(dir.path()).ok_or("temp dir is not UTF-8")?;
94	/// let request = SearchRequest {
95	///     root,
96	///     query: "alpha",
97	///     exact: false,
98	///     allow_tests: false,
99	///     respect_ignore_files: true,
100	///     language: None,
101	/// };
102	///
103	/// // With no analyzer registered, the file matches but yields no blocks.
104	/// let result = search(&AnalyzerRegistry::new(Vec::new()), &request)?;
105	/// assert_eq!(result.files_total, 1);
106	/// assert!(result.ranked.is_empty());
107	/// # Ok::<(), Box<dyn std::error::Error>>(())
108	/// ```
109	pub fn search(registry: &AnalyzerRegistry, request: &SearchRequest<'_>) -> Result<SearchResult> {
110	    search_with_ceiling(registry, request, DEFAULT_MAX_FILES)
111	}
112	
113	/// [`search`] with the file ceiling as a parameter, so tests can reach it without 100,000 files.
114	fn search_with_ceiling(
115	    registry: &AnalyzerRegistry,
116	    request: &SearchRequest<'_>,
117	    max_files: usize,
118	) -> Result<SearchResult> {
119	    let SearchRequest { root, query, exact, allow_tests, respect_ignore_files, language } = *request;
120	    if let Some(language) = language
121	        && !is_supported(language)
122	    {
123	        return Ok(SearchResult::skipped(format!(
124	            "language {language:?} not supported in v1; only TypeScript/JavaScript"
125	        )));
126	    }
127	
128	    let terms = if exact {
129	        if query.trim().is_empty() {
130	            Vec::new()
131	        } else {
132	            vec![ParsedTerm { modifier: Modifier::Optional, pattern: regex::escape(query), is_regex: false }]
133	        }
134	    } else {
135	        parse(query)?
136	    };
137	    let plan = QueryPlan::from_terms(terms);
138	    let patterns = plan.search_patterns();
139	    if patterns.is_empty() {
140	        return Ok(SearchResult::skipped("query has no positive terms; add a term without a leading `-`"));
141	    }
142	
143	    // Every term, excluded ones too, compiles before any file is read, so an invalid one fails the whole query.
144	    let matchers = plan.terms.iter().map(|term| compile(&term.pattern)).collect::<Result<Vec<_>>>()?;
145	    let root = canonicalize(root)?;
146	
147	    let found = search_files(&root, &patterns, &TextSearchOptions { allow_tests, respect_ignore_files, max_files })?;
148	    let mut diagnostics = text_search_diagnostics(&found);
149	
150	    // The ceiling must not apply here: an excluded file past it would wrongly survive.
151	    let excluded_files = if found.hits.is_empty() || plan.excluded.is_empty() {
152	        BTreeSet::new()
153	    } else {
154	        let excluded_patterns: Vec<&str> = plan.excluded.iter().map(|&i| plan.terms[i].pattern.as_str()).collect();
155	        let excluded = search_files(
156	            &root,
157	            &excluded_patterns,
158	            &TextSearchOptions { allow_tests, respect_ignore_files, max_files: usize::MAX },
159	        )?;
160	        // The walk is the same, so only a file unreadable for the excluded patterns alone is new.
161	        for path in &excluded.unreadable {
162	            if !found.unreadable.contains(path) {
163	                diagnostics.push(unreadable_diagnostic(path));
164	            }
165	        }
166	        excluded.hits.into_keys().collect()
167	    };
168	
169	    let mut candidates: Vec<(CodeBlock, Vec<String>)> = Vec::new();
170	    for (path, hits) in &found.hits {
171	        if excluded_files.contains(path) {
172	            continue;
173	        }
174	        let has_every_required =
175	            plan.required.iter().all(|&i| hits.iter().any(|hit| matches_text(&matchers[i], &hit.text)));
176	        if !has_every_required {
177	            continue;
178	        }
179	        let ctx = FileContext { registry, plan: &plan, matchers: &matchers, language };
180	        retrieve_blocks(&ctx, path, hits, &read_source, &mut candidates, &mut diagnostics);
181	    }
182	
183	    let bm25_terms = bm25_terms(&plan);
184	    let df = document_frequencies(&candidates, &bm25_terms);
185	    let bm25_terms: Vec<&str> = bm25_terms.iter().map(String::as_str).collect();
186	    let ranked = dedup_blocks(rank_blocks(candidates, &bm25_terms, &df));
187	
188	    Ok(SearchResult { ranked, files_total: found.files_total, ceiling_hit: found.ceiling_hit, diagnostics })
189	}
