191	/// Returns whether `language` has an analyzer path in v1.
192	fn is_supported(language: Language) -> bool {
193	    match language {
194	        Language::TypeScript | Language::JavaScript => true,
195	        Language::Rust | Language::Python => false,
196	    }
197	}
198	
199	/// Compiles one term the way text search does, case-insensitively, so a term can never match differently here.
200	fn compile(pattern: &str) -> Result<RegexMatcher> {
201	    Ok(RegexMatcherBuilder::new().case_insensitive(true).build(pattern)?)
202	}
203	
204	fn canonicalize(root: &Utf8Path) -> Result<Utf8PathBuf> {
205	    let path = root.as_std_path().canonicalize().map_err(|source| FileIoError::read(root, source))?;
206	    Utf8PathBuf::from_path_buf(path).map_err(|path| MonoklError::NonUtf8Path { path })
207	}
208	
209	/// A file's text, and whether getting it meant replacing bytes that are not UTF-8.
210	struct Source {
211	    text: String,
212	    lossy: bool,
213	}
214	
215	/// Reads `path`, replacing each invalid UTF-8 sequence with U+FFFD so the file is still searched and extracted.
216	fn read_source(path: &Utf8Path) -> io::Result<Source> {
217	    let bytes = std::fs::read(path)?;
218	    Ok(match String::from_utf8(bytes) {
219	        Ok(text) => Source { text, lossy: false },
220	        Err(err) => Source { text: String::from_utf8_lossy(err.as_bytes()).into_owned(), lossy: true },
221	    })
222	}
223	
224	/// Whether `matcher` matches `text`. Matching in memory cannot fail, so an error counts as no match.
225	fn matches_text(matcher: &RegexMatcher, text: &str) -> bool {
226	    matches!(matcher.is_match(text.as_bytes()), Ok(true))
227	}
228	
229	fn skipped(path: Option<&Utf8Path>, message: impl Into<String>) -> Diagnostic {
230	    Diagnostic { kind: DiagnosticKind::Skipped, path: path.map(Utf8Path::to_owned), message: message.into() }
231	}
232	
233	fn unreadable_diagnostic(path: &Utf8Path) -> Diagnostic {
234	    skipped(Some(path), "file could not be read")
235	}
236	
237	/// Turns what text search could not read into diagnostics: one per unreadable path, then one per non-zero count.
238	fn text_search_diagnostics(found: &TextSearchResult) -> Vec<Diagnostic> {
239	    let mut diagnostics: Vec<Diagnostic> = found.unreadable.iter().map(|path| unreadable_diagnostic(path)).collect();
240	    if found.non_utf8_paths > 0 {
241	        diagnostics.push(skipped(None, format!("{} files skipped: path is not valid UTF-8", found.non_utf8_paths)));
242	    }
243	    if found.walk_errors_without_path > 0 {
244	        diagnostics.push(skipped(
245	            None,
246	            format!("{} directory walk errors did not name a UTF-8 path", found.walk_errors_without_path),
247	        ));
248	    }
249	    diagnostics
250	}
