252	/// What block retrieval needs besides the file itself.
253	struct FileContext<'a> {
254	    registry: &'a AnalyzerRegistry,
255	    plan: &'a QueryPlan,
256	    matchers: &'a [RegexMatcher],
257	    language: Option<Language>,
258	}
