260	/// The TypeScript analyzer owns both languages, so the `--language` filter goes by extension.
261	fn has_language_extension(language: Language, path: &Utf8Path) -> bool {
262	    match language {
263	        Language::TypeScript => matches!(path.extension(), Some("ts" | "tsx" | "mts" | "cts")),
264	        Language::JavaScript => matches!(path.extension(), Some("js" | "jsx" | "mjs" | "cjs")),
265	        Language::Rust | Language::Python => false,
266	    }
267	}
